/** Add this file to each SCHOOL'S own Apps Script project.
 * Install alongside SaarthiSchool.gs and SaarthiStorage.gs (one doPost only).
 * Run VS_setupSchool('your-school-firebase-project-id', 'your-school-api-key') once as script owner.
 * All Firestore calls use the script owner's OAuth identity. Never expose it.
 */
function VS_setupSchool(projectId, apiKey) {
  if(projectId==='saarthi-ai-df12b')throw new Error('The developer Firebase is only for website monitoring/licensing. Use this school\'s separate Firebase project.');
  if (!/^[a-z][a-z0-9-]{4,61}[a-z0-9]$/.test(projectId)) throw new Error('Invalid Firebase project ID');
  if(!/^AIza[A-Za-z0-9_-]{20,}$/.test(String(apiKey||'')))throw new Error('Supply this school Firebase Web API key as the second setup argument');
  const props = PropertiesService.getScriptProperties();
  const previous = props.getProperty('VS_FIREBASE_PROJECT_ID');
  if (previous && previous !== projectId) throw new Error('Use a separate Apps Script project for each school; rebinding is blocked');
  props.setProperty('VS_FIREBASE_PROJECT_ID', projectId);
  props.setProperty('VS_FIREBASE_API_KEY', String(apiKey));
  VS_firestore('GET', 'school_settings/calendar');
  if (!props.getProperty('VS_DRIVE_ROOT_ID')) {
    const root = DriveApp.createFolder('VidyaSaarthi_' + projectId);
    root.setDescription('SAARTHI_SCHOOL_PROJECT:' + projectId);
    props.setProperty('VS_DRIVE_ROOT_ID', root.getId());
    props.setProperty('VS_STORAGE_READY', 'false');
  }
  return {projectId: projectId, rootFolderId: VS_schoolDriveRoot(true).getId(), storageReady: props.getProperty('VS_STORAGE_READY') === 'true'};
}
function VS_project() { const p=PropertiesService.getScriptProperties().getProperty('VS_FIREBASE_PROJECT_ID'); if(!p)throw new Error('School mobile integration has not been configured');return p; }
function VS_hash(s) {return Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256,String(s)).map(v=>('0'+((v+256)%256).toString(16)).slice(-2)).join('');}
function VS_secret() {return Utilities.getUuid().replace(/-/g,'')+Utilities.getUuid().replace(/-/g,'');}
function VS_encode(v) {if(v===null||v===undefined)return {nullValue:null};if(typeof v==='boolean')return {booleanValue:v};if(typeof v==='number')return Number.isInteger(v)?{integerValue:String(v)}:{doubleValue:v};if(Array.isArray(v))return {arrayValue:{values:v.map(VS_encode)}};if(typeof v==='object'){const fields={};Object.keys(v).forEach(k=>fields[k]=VS_encode(v[k]));return {mapValue:{fields:fields}};}return {stringValue:String(v)};}
function VS_decode(v) {if(v.stringValue!==undefined)return v.stringValue;if(v.integerValue!==undefined)return Number(v.integerValue);if(v.doubleValue!==undefined)return v.doubleValue;if(v.booleanValue!==undefined)return v.booleanValue;if(v.timestampValue!==undefined)return Date.parse(v.timestampValue);if(v.mapValue){const o={};Object.keys(v.mapValue.fields||{}).forEach(k=>o[k]=VS_decode(v.mapValue.fields[k]));return o;}if(v.arrayValue)return (v.arrayValue.values||[]).map(VS_decode);return null;}
function VS_doc(raw) {if(!raw||!raw.fields)return null;const o={id:raw.name.split('/').pop()};Object.keys(raw.fields).forEach(k=>o[k]=VS_decode(raw.fields[k]));return o;}
function VS_firestore(method,path,data) {
 const base='https://firestore.googleapis.com/v1/projects/'+encodeURIComponent(VS_project())+'/databases/(default)/documents/';
 const opt={method:method,muteHttpExceptions:true,headers:{Authorization:'Bearer '+ScriptApp.getOAuthToken()}};
 if(data){opt.contentType='application/json';opt.payload=JSON.stringify(data);}
 const r=UrlFetchApp.fetch((path[0]===':'?base.slice(0,-1):base)+path,opt);const code=r.getResponseCode();if(code===404)return null;const body=JSON.parse(r.getContentText()||'{}');if(code>=400)throw new Error('School database operation failed ('+code+')');return body;
}
function VS_get(col,id){return VS_doc(VS_firestore('GET',col+'/'+encodeURIComponent(id)));}
function VS_set(col,id,data){const fields={};const text=firebaseTextOnlyValue_(data);Object.keys(text).forEach(k=>fields[k]=VS_encode(text[k]));return VS_doc(VS_firestore('PATCH',col+'/'+encodeURIComponent(id),{fields:fields}));}
function VS_query(col,field,value){const query={from:[{collectionId:col}]};if(field)query.where={fieldFilter:{field:{fieldPath:field},op:'EQUAL',value:VS_encode(value)}};const result=VS_firestore('POST',':runQuery',{structuredQuery:query})||[];return result.filter(r=>r.document).map(r=>VS_doc(r.document));}
function VS_dob(raw){if(raw instanceof Date&&!isNaN(raw.getTime()))return Utilities.formatDate(raw,'Asia/Kolkata','yyyy-MM-dd');const s=String(raw||'').trim();const m=s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);if(m)return m[3]+'-'+('0'+m[2]).slice(-2)+'-'+('0'+m[1]).slice(-2);const iso=s.match(/^(\d{4})-(\d{2})-(\d{2})/);if(iso)return iso[0];return s.toLowerCase();}
function VS_day(){return Utilities.formatDate(new Date(),'Asia/Kolkata','yyyy-MM-dd');}
function VS_isOpen(day){const d=VS_get('school_calendar',day);if(d&&typeof d.isOpen==='boolean')return d.isOpen;const config=VS_get('school_settings','calendar')||{};const closed=config.closedWeekdays||[0];return closed.indexOf(new Date(day+'T12:00:00+05:30').getUTCDay())<0;}
function VS_person(b){const type=b.role||b.type;if(type!=='student'&&type!=='teacher')throw new Error('Invalid QR role');const col=type==='teacher'?'teachers_directory':'students_directory';const token=String(b.linkToken||'');if(token.length<20)throw new Error('This ID card needs a new secure school QR');let p=VS_get(col,String(b.personId||''));if(!p||p.mobileLinkToken!==token){const found=VS_query(col,'mobileLinkToken',token);p=found.length===1?found[0]:null;}if(!p||p.mobileLinkToken!==token)throw new Error('This QR does not belong to the active school');return {person:p,role:type};}
function VS_session(b){const token=String(b.sessionToken||'');if(token.length<40)throw new Error('School login required');const doc=VS_get('mobile_sessions',VS_hash(token));if(!doc||doc.expiresAt<=Date.now())throw new Error('School session expired');let person=VS_get(doc.role==='teacher'?'teachers_directory':'students_directory',doc.documentId);if(!person||person.mobileLinkToken!==doc.linkToken){const found=VS_query(doc.role==='teacher'?'teachers_directory':'students_directory','mobileLinkToken',doc.linkToken);person=found.length===1?found[0]:null;}if(!person||person.mobileLinkToken!==doc.linkToken)throw new Error('School record or ID card was changed; scan again');return {doc:doc,person:person,role:doc.role,personId:person.mobileStableId||doc.personId};}
function VS_own(col,session){const records=VS_query(col,'personId',session.personId).concat(VS_query(col,'studentId',session.person.id));const seen={};return records.filter(d=>{if(d.personId){if(d.personId!==session.personId)return false;}else{const name=String(d.studentName||d.name||'').trim().toLowerCase(),owner=String(session.person.name||'').trim().toLowerCase();if(!name||name!==owner)return false;if((d.dob||d.dateOfBirth)&&VS_dob(d.dob||d.dateOfBirth)!==VS_dob(session.person.dob||session.person.dateOfBirth))return false;}if(seen[d.id])return false;seen[d.id]=true;return true;});}
function VS_safePerson(p){const allowed=['id','name','class','rollNo','dob','dateOfBirth','parentName','fatherName','parentContact','photoUrl','studentUid','teacherId','designation','subject','idCardUrl','mobileStableId'];const out={};allowed.forEach(k=>{if(p[k]!==undefined)out[k]=p[k];});return out;}
function VS_distance(a,b,c,d){const rad=x=>x*Math.PI/180;const h=Math.sin(rad(c-a)/2)**2+Math.cos(rad(a))*Math.cos(rad(c))*Math.sin(rad(d-b)/2)**2;return 6371000*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h));}
function VS_handleMobile(e){
 let b;try{b=JSON.parse(e.postData.contents);}catch(_){return null;}
 if(!String(b.action||'').startsWith('mobile_')){
  try{
   VS_requireAdmin(b);
   VS_schoolSyncGuard(b);
   if(String(b.action||'').startsWith('platform_'))return ContentService.createTextOutput(JSON.stringify(Object.assign({success:true,projectId:VS_project()},VS_platformAdmin(b)))).setMimeType(ContentService.MimeType.JSON);
   if(['mark_attendance','mark_student_attendance','mark_teacher_attendance'].indexOf(b.action)>=0&&!VS_isOpen(VS_day()))throw new Error('School is closed today. Attendance is disabled for everyone');
   if(b.action==='change_student_class' && b.newRollNo!==undefined)return ContentService.createTextOutput(JSON.stringify(Object.assign({success:true,projectId:VS_project()},VS_changeStudentClass(b)))).setMimeType(ContentService.MimeType.JSON);
   return null;
  }catch(err){return ContentService.createTextOutput(JSON.stringify({success:false,code:'SCHOOL_ADMIN_REQUIRED',message:String(err.message||err)})).setMimeType(ContentService.MimeType.JSON);}
 }
 let result;
 try{result=VS_mobileAction(b);result=Object.assign({success:true,projectId:VS_project()},result);}catch(err){result={success:false,message:String(err.message||err)};}
 return ContentService.createTextOutput(JSON.stringify(result)).setMimeType(ContentService.MimeType.JSON);
}
function VS_mobileAction(b){
 const action=b.action;
 if(action==='mobile_project_info')return {projectId:VS_project(),windowsAdminProtection:!!PropertiesService.getScriptProperties().getProperty('VS_FIREBASE_API_KEY'),mobileProtocol:3};
 if(action==='mobile_login'){
  const expected=VS_project();if(b.projectId!==expected)throw new Error('The QR Firebase project and this school backend do not match');
  const verified=VS_person(b);const p=verified.person;
  if(verified.role==='student'){
   const selected=String(b.studentClass||'').replace(/[^0-9]/g,'');const assigned=String(p.class||'').replace(/[^0-9]/g,'');
   const roll=String(b.rollNo||'').replace(/^0+/,'');const savedRoll=String(p.rollNo||'').replace(/^0+/,'');
   if(!selected||selected!==assigned||!roll||roll!==savedRoll||!VS_dob(b.dob)||!VS_dob(p.dob||p.dateOfBirth)||VS_dob(b.dob)!==VS_dob(p.dob||p.dateOfBirth))throw new Error('Class, roll number or date of birth is incorrect');
  }
  VS_requireLicense();
  const token=VS_secret();const expires=Date.now()+30*86400000;const stable=p.mobileStableId||p.id;
  VS_set('mobile_sessions',VS_hash(token),{personId:stable,documentId:p.id,role:verified.role,linkToken:p.mobileLinkToken,expiresAt:expires,createdAt:Date.now()});
  VS_set('mobile_users',VS_hash(verified.role+'/'+stable),{role:verified.role});
  return {sessionToken:token,personId:stable,role:verified.role,expiresAt:expires,person:VS_safePerson(p),messaging:VS_messagingOptions(),schoolName:VS_project()};
 }
 if(b.projectId && b.projectId!==VS_project())throw new Error('School identity mismatch');
 const session=VS_session(b);
 if(action!=='mobile_session_verify'&&action!=='mobile_logout')VS_requireLicense();
 if(action==='mobile_session_verify')return {personId:session.personId,role:session.role,expiresAt:session.doc.expiresAt};
 if(action==='mobile_logout'){VS_firestore('DELETE','mobile_sessions/'+VS_hash(b.sessionToken));return {loggedOut:true};}
 if(action==='mobile_heartbeat'){VS_touchPresence(session,b.version);return {allowed:true};}
 if(action==='mobile_messaging_config')return {messaging:VS_messagingOptions()};
 if(action==='mobile_complaint')return VS_queueComplaint(b,session.role,'android',session.personId);
 if(action==='mobile_notice'){const notice=VS_get('school_notices',String(b.noticeId||''));if(!notice)throw new Error('School notice unavailable');return {notice:notice};}
 if(action==='mobile_asset')return VS_mobileAsset(b,session);
 if(action==='mobile_dashboard'){
  VS_touchPresence(session,b.version);
  const profile=VS_mobileSchoolProfile();
  const notices=VS_query('school_notices').sort((a,c)=>(c.timestamp||c.createdAt||0)-(a.timestamp||a.createdAt||0)).slice(0,100);
  const result={person:VS_safePerson(session.person),school:profile,notices:notices,templates:VS_get('school_settings','document_templates')||{},calendar:VS_query('school_calendar'),calendarSettings:VS_get('school_settings','calendar')||{closedWeekdays:[0]}};
  if(session.role==='student'){
   result.reportCards=VS_own('exam_results',session);
   result.fees=VS_own('fee_ledger',session);
   result.payments=VS_own('fee_payments',session);
  }else{result.salary=VS_query('teacher_salary','teacherId',session.person.teacherId||session.person.id);}
  return result;
 }
 if(action==='mobile_attendance_list'){
  const month=String(b.month||'');if(!/^\d{4}-\d{2}$/.test(month))throw new Error('Select a month');
  return {attendance:VS_query('attendance_records','personId',session.personId).filter(d=>String(d.date||'').startsWith(month)),calendar:VS_query('school_calendar').filter(d=>d.id.startsWith(month)),calendarSettings:VS_get('school_settings','calendar')||{closedWeekdays:[0]}};
 }
 if(action==='mobile_mark_attendance'){
  const day=VS_day();if(!VS_isOpen(day))throw new Error('School is closed today. Attendance is disabled for everyone');
  const loc=VS_get('school_settings','school_location')||{};const lat=Number(b.latitude),lng=Number(b.longitude);
  if(!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>90||Math.abs(lng)>180)throw new Error('Enable your device location');
  if(loc.latitude===undefined||loc.longitude===undefined)throw new Error('School location is not configured');
  const distance=VS_distance(lat,lng,Number(loc.latitude),Number(loc.longitude));if(distance>Number(loc.radiusMeters||200))throw new Error('Attendance can be marked only within the school location');
  // A scan at attendance time must be the same person as the verified session.
  const qr=VS_person(b);if(qr.role!==session.role||qr.person.mobileLinkToken!==session.person.mobileLinkToken)throw new Error('Scan your own school ID card');
  const id=VS_hash(session.role+'/'+session.personId+'/'+day);const lock=LockService.getScriptLock();lock.waitLock(20000);
  try{
   const current=VS_get('attendance_records',id)||{};const mode=b.mode==='exit'?'exit':'entry';
   if(mode==='entry'&&current.checkIn)throw new Error('Today’s check-in is already recorded');
   if(mode==='exit'&&!current.checkIn)throw new Error('Check in before checking out');
   if(mode==='exit'&&current.checkOut)throw new Error('Today’s check-out is already recorded');
   const doc=Object.assign({},current,{personId:session.personId,documentId:session.person.id,role:session.role,name:session.person.name||'',studentClass:session.person.class||'',rollNo:session.person.rollNo||'',date:day,source:'ANDROID_QR',updatedAt:Date.now()});delete doc.id;
   doc[mode==='entry'?'checkIn':'checkOut']=Date.now();VS_set('attendance_records',id,doc);
   return {message:mode==='entry'?'Check-in recorded':'Check-out recorded',record:doc};
  }finally{lock.releaseLock();}
 }
 throw new Error('Unknown school mobile action');
}

function VS_requireLicense(){
 const lease=VS_platformStatus();
 if(!lease.allowed||lease.expiresAt<=Date.now())throw new Error('School trial or licence has ended');
}

// Legacy Windows actions carry a refreshed Firebase ID token. A QR exposes only
// public connection details, never an administrator token or an owner credential.
function VS_requireAdmin(b){
 const project=VS_project();const apiKey=PropertiesService.getScriptProperties().getProperty('VS_FIREBASE_API_KEY');
 if(!apiKey)throw new Error('School owner must complete VS_setupSchool(projectId, apiKey)');
 const token=String(b.schoolAdminIdToken||'');if(b.schoolProjectId!==project||token.length<40)throw new Error('This school administrator login is required');
 const cache=CacheService.getScriptCache(),key='VS_ADMIN_'+VS_hash(project+'/'+token);if(cache.get(key)==='ok')return;
 let claims;try{claims=JSON.parse(Utilities.newBlob(Utilities.base64DecodeWebSafe(token.split('.')[1])).getDataAsString());}catch(_){throw new Error('Invalid school administrator token');}
 if(claims.aud!==project||claims.iss!=='https://securetoken.google.com/'+project||claims.exp*1000<=Date.now()||(claims.admin!==true&&claims.role!=='admin'))throw new Error('Administrator proof belongs to a different school or has expired');
 // accounts:lookup verifies the complete signed Firebase ID token, not just its payload.
 const r=UrlFetchApp.fetch('https://identitytoolkit.googleapis.com/v1/accounts:lookup?key='+encodeURIComponent(apiKey),{method:'post',contentType:'application/json',payload:JSON.stringify({idToken:token}),muteHttpExceptions:true});
 const d=JSON.parse(r.getContentText());const user=(d.users||[])[0];
 if(r.getResponseCode()!==200||!user||user.disabled||user.localId!==claims.sub||Number(user.validSince||0)>Number(claims.auth_time||0))throw new Error('School administrator verification failed');
 cache.put(key,'ok',Math.max(1,Math.min(60,Math.floor(claims.exp-Date.now()/1000))));
}

// Uses the existing school sheet helpers. A free destination roll avoids the
// normal annual collision when the older class has not finished its exam yet.
function VS_changeStudentClass(b){
 if(typeof getOrCreateDatabaseSheet!=='function'||typeof findStudentRow!=='function')throw new Error('This school backend needs the current student sheet helpers');
 const oldClass=String(b.oldClass||''),newClass=String(b.newClass||''),oldRoll=String(b.rollNo||''),newRoll=String(b.newRollNo||oldRoll);
 if(!oldClass||!newClass||!/^\d+$/.test(oldRoll)||!/^\d+$/.test(newRoll))throw new Error('Valid class and roll required');
 const sheet=getOrCreateDatabaseSheet(STUDENT_SHEET_NAME,STUDENT_HEADERS),lock=LockService.getScriptLock();lock.waitLock(20000);
 try{
  const from=findStudentRow(sheet,oldClass,oldRoll),to=findStudentRow(sheet,newClass,newRoll);
  function samePerson(row){return String(b.studentName||'').trim().toLowerCase()===String(row[0]||'').trim().toLowerCase()&&(!b.dob||VS_dob(b.dob)===VS_dob(row[STUDENT_HEADERS.indexOf('Date of Birth')]));}
  if(from===-1&&to>1){if(!samePerson(sheet.getRange(to,1,1,STUDENT_HEADERS.length).getValues()[0]))throw new Error('Destination belongs to another student');return {alreadyChanged:true,newClass:newClass,rollNo:newRoll};}
  if(from===-1)throw new Error('Student old class not found');
  if(to>1&&to!==from)throw new Error('Destination roll is occupied; refresh and retry');
  const studentRange=sheet.getRange(from,1,1,STUDENT_HEADERS.length),previousStudent=studentRange.getValues(),nextStudent=previousStudent.map(row=>row.slice());
  if(!samePerson(previousStudent[0]))throw new Error('Student record changed; refresh before promotion');
  nextStudent[0][2]=newClass;nextStudent[0][3]=newRoll;nextStudent[0][STUDENT_HEADERS.length-1]=new Date();
  const documents=getOrCreateDatabaseSheet(STUDENT_DOCUMENT_INDEX_SHEET,STUDENT_DOCUMENT_HEADERS);
  let documentRange,previousDocuments,nextDocuments,changed=false;
  if(documents.getLastRow()>1){documentRange=documents.getRange(2,1,documents.getLastRow()-1,STUDENT_DOCUMENT_HEADERS.length);previousDocuments=documentRange.getValues();nextDocuments=previousDocuments.map(row=>row.slice());nextDocuments.forEach(row=>{if(String(row[1])===String(b.oldStudentId)||(normalizeClass(row[3])===normalizeClass(oldClass)&&normalizeRoll(row[4])===normalizeRoll(oldRoll))){row[1]=b.newStudentId;row[3]=newClass;row[4]=newRoll;changed=true;}});}
  try{studentRange.setValues(nextStudent);if(changed)documentRange.setValues(nextDocuments);}
  catch(error){studentRange.setValues(previousStudent);if(changed)documentRange.setValues(previousDocuments);throw error;}
  return {newClass:newClass,rollNo:newRoll,oldStudentId:b.oldStudentId,newStudentId:b.newStudentId};
 }finally{lock.releaseLock();}
}

/** Spark platform bridge. Install ONLY in this school's own Apps Script.
 * The developer website provisions a school-scoped monitoring identity.
 * No student record, QR, session token, FCM token or owner OAuth goes centrally.
 */
const VS_CENTRAL_PROJECT = 'saarthi-ai-df12b';
const VS_CENTRAL_API_KEY = 'AIzaSyDherXWiNIbKzO8EFuf1VdpHvu7U6R-W3A';
function VS_centralBase(){return 'https://firestore.googleapis.com/v1/projects/'+VS_CENTRAL_PROJECT+'/databases/(default)/documents';}
function VS_central(method,path,data,token){
 const options={method:method,muteHttpExceptions:true,headers:{}};
 if(token)options.headers.Authorization='Bearer '+token;
 if(data){options.contentType='application/json';options.payload=JSON.stringify(data);}
 const r=UrlFetchApp.fetch(VS_centralBase()+(path[0]===':'?'':'/')+path,options);
 const code=r.getResponseCode();let body;try{body=JSON.parse(r.getContentText()||'{}');}catch(_){throw new Error('Developer monitoring service unavailable');}
 if(code===404)return null;
 if(code>=400){const err=new Error('Developer monitoring operation failed ('+code+')');err.httpCode=code;throw err;}
 return body;
}
function VS_centralAuth(action,data){
 const r=UrlFetchApp.fetch('https://identitytoolkit.googleapis.com/v1/accounts:'+action+'?key='+VS_CENTRAL_API_KEY,
  {method:'post',contentType:'application/json',payload:JSON.stringify(data),muteHttpExceptions:true});
 const result=JSON.parse(r.getContentText()||'{}');
 if(r.getResponseCode()!==200)throw new Error('Developer Firebase authentication unavailable. Check the school monitoring setup and enabled sign-in providers.');
 return result;
}
function VS_schoolTrial(device){
 const path='platform_school_trials/'+VS_project();let raw=VS_central('get',path);
 if(!raw){
  if(!/^[a-f0-9]{64}$/.test(String(device||'')))throw new Error('Connect the Windows app first to verify this school trial');
  const original=VS_central('get','platform_device_trials/'+device);
  if(!original||!original.fields||!original.fields.createdAt)throw new Error('Windows device trial has not been verified yet');
  const auth=VS_centralAuth('signUp',{returnSecureToken:true});
  try{
   VS_central('post',':commit',{writes:[{update:{name:'projects/'+VS_CENTRAL_PROJECT+'/databases/(default)/documents/'+path,
    fields:{createdAt:original.fields.createdAt,deviceTrialId:VS_encode(device)}},currentDocument:{exists:false}},
    {update:{name:'projects/'+VS_CENTRAL_PROJECT+'/databases/(default)/documents/platform_trial_claims/'+auth.localId,fields:{target:VS_encode(path)}},
     currentDocument:{exists:false},updateTransforms:[{fieldPath:'createdAt',setToServerValue:'REQUEST_TIME'}]}]},auth.idToken);
  }catch(err){if(err.httpCode!==409)throw err;}
  finally{try{VS_centralAuth('delete',{idToken:auth.idToken});}catch(_) {}}
  raw=VS_central('get',path);
 }
 if(!raw)throw new Error('School trial verification unavailable');
 return VS_doc(raw).createdAt;
}
function VS_platformStatus(force){
 const props=PropertiesService.getScriptProperties(),cache=CacheService.getScriptCache(),key='VS_PLATFORM_STATUS';
 if(!force){const cached=cache.get(key);if(cached){const d=JSON.parse(cached);if(d.expiresAt<=Date.now()){d.allowed=false;if(d.status!=='blocked')d.status='expired';}return d;}}
 const hash=props.getProperty('VS_LICENSE_KEY_HASH');let status,expires;
 if(hash){
  const raw=VS_central('get','platform_license_status/'+hash),license=VS_doc(raw);
  if(!license||license.schoolId!==VS_project())throw new Error('Licence does not belong to this school');
  expires=license.expiresAt;status=license.revoked?'blocked':expires>Date.now()?'licensed':'expired';
 }else{expires=VS_schoolTrial()+5*86400000;status=expires>Date.now()?'trial':'expired';}
 const result={schoolId:VS_project(),allowed:status==='trial'||status==='licensed',status:status,expiresAt:expires,serverTime:Date.now(),licenseHash:hash||null};
 cache.put(key,JSON.stringify(result),300);return result;
}
function VS_setupPlatform(bundle){
 if(!bundle||bundle.projectId!==VS_project())throw new Error('Monitoring setup belongs to a different school');
 if(!/^monitor-[a-f0-9]{24}@vidyasaarthi\.invalid$/.test(String(bundle.monitorEmail||''))||!/^[a-f0-9]{48}$/.test(String(bundle.monitorPassword||'')))throw new Error('Copy a fresh school setup from the developer website');
 const auth=VS_centralAuth('signInWithPassword',{email:bundle.monitorEmail,password:bundle.monitorPassword,returnSecureToken:true});
 const props=PropertiesService.getScriptProperties();
 props.setProperties({VS_MONITOR_EMAIL:bundle.monitorEmail,VS_MONITOR_PASSWORD:bundle.monitorPassword,VS_MONITOR_ID_TOKEN:auth.idToken,VS_MONITOR_TOKEN_UNTIL:String(Date.now()+3500000)});
 if(bundle.licenseKey)VS_activatePlatformLicense(bundle.licenseKey);
 const installed=ScriptApp.getProjectTriggers().some(t=>t.getHandlerFunction()==='VS_platformMaintenance');
 if(!installed)ScriptApp.newTrigger('VS_platformMaintenance').timeBased().everyMinutes(5).create();
 VS_publishMonitor();return {projectId:VS_project(),configured:true};
}
function VS_monitorToken(){
 const p=PropertiesService.getScriptProperties();if(!p.getProperty('VS_MONITOR_EMAIL'))return '';
 if(Number(p.getProperty('VS_MONITOR_TOKEN_UNTIL'))>Date.now())return p.getProperty('VS_MONITOR_ID_TOKEN');
 const a=VS_centralAuth('signInWithPassword',{email:p.getProperty('VS_MONITOR_EMAIL'),password:p.getProperty('VS_MONITOR_PASSWORD'),returnSecureToken:true});
 p.setProperties({VS_MONITOR_ID_TOKEN:a.idToken,VS_MONITOR_TOKEN_UNTIL:String(Date.now()+3500000)});return a.idToken;
}
function VS_activatePlatformLicense(key){
 key=String(key||'').trim().toUpperCase();if(!/^VS-[A-F0-9]{32}$/.test(key))throw new Error('Enter the licence key supplied by the developer');
 const hash=VS_hash(key),doc=VS_doc(VS_central('get','platform_license_status/'+hash));
 if(!doc||doc.schoolId!==VS_project()||doc.revoked||doc.expiresAt<=Date.now())throw new Error('Licence is expired, revoked or belongs to a different school');
 PropertiesService.getScriptProperties().setProperty('VS_LICENSE_KEY_HASH',hash);
 CacheService.getScriptCache().remove('VS_PLATFORM_STATUS');return VS_platformStatus(true);
}
function VS_platformAdmin(b){
 if(b.schoolProjectId!==VS_project())throw new Error('School identity mismatch');
 const p=PropertiesService.getScriptProperties();
 if(b.action==='platform_activate')return VS_activatePlatformLicense(b.key);
 if(b.action==='platform_notice'){VS_notifySchoolNotice(String(b.noticeId||''));return {sent:true};}
 if(b.action==='platform_complaint')return VS_queueComplaint(b,'admin','windows');
 if(b.action==='platform_bind'||b.action==='platform_heartbeat'){
  if(b.action==='platform_bind'&&!p.getProperty('VS_LICENSE_KEY_HASH'))VS_schoolTrial(b.deviceFingerprint);
  p.setProperty('VS_WINDOWS_LAST_ACTIVE',String(Date.now()));
  if(b.version)p.setProperty('VS_WINDOWS_VERSION',String(b.version).slice(0,32));
  // Publishing an aggregate can fail without blocking the school licence.
  try{VS_publishMonitor();}catch(err){console.warn(String(err.message||err));}
  return VS_platformStatus(b.action==='platform_bind');
 }
 if(b.action==='platform_status')return VS_platformStatus();
 throw new Error('Unknown school platform action');
}
function VS_count(col,field,value){
 const query={from:[{collectionId:col}]};
 if(field)query.where={fieldFilter:{field:{fieldPath:field},op:'EQUAL',value:VS_encode(value)}};
 const raw=VS_firestore('post',':runAggregationQuery',{structuredAggregationQuery:{structuredQuery:query,aggregations:[{alias:'total',count:{}}]}})||[];
 return Number(raw[0]&&raw[0].result&&raw[0].result.aggregateFields.total.integerValue||0);
}
function VS_touchPresence(session,version){
 // Approximate live counts are cached in this school only. Eviction can lower
 // the estimate; these caches never authorise access or validate a licence.
 const cache=CacheService.getScriptCache(),id=VS_hash(session.role+'/'+session.personId).slice(0,24),shard=id[0],key='VS_PRESENCE_'+shard;
 const lock=LockService.getScriptLock();if(!lock.tryLock(3000))return;
 try{
  const bucket=JSON.parse(cache.get(key)||'{}'),now=Date.now();
  Object.keys(bucket).forEach(k=>{if(bucket[k].at<now-300000)delete bucket[k];});
  bucket[id]={at:now,role:session.role};cache.put(key,JSON.stringify(bucket),600);
  cache.put('VS_ACTIVITY_AT',String(now),21600);
  if(version)cache.put('VS_MOBILE_VERSION',String(version).slice(0,32),21600);
 }finally{lock.releaseLock();}
}
function VS_presenceCounts(){
 const cache=CacheService.getScriptCache(),now=Date.now();let students=0,teachers=0;
 '0123456789abcdef'.split('').forEach(shard=>{
  const bucket=JSON.parse(cache.get('VS_PRESENCE_'+shard)||'{}');
  Object.keys(bucket).forEach(k=>{const d=bucket[k];if(d.at>=now-300000){if(d.role==='student')students++;else if(d.role==='teacher')teachers++;}});
 });return {students:students,teachers:teachers};
}
function VS_publishMonitor(){
 const p=PropertiesService.getScriptProperties();if(!p.getProperty('VS_MONITOR_EMAIL'))return;
 const lock=LockService.getScriptLock();if(!lock.tryLock(3000))return;
 try{
  if(Date.now()-Number(p.getProperty('VS_MONITOR_LAST_SENT')||0)<301000)return;
  const online=VS_presenceCounts(),data={schoolId:VS_project(),studentCount:VS_count('students_directory'),teacherCount:VS_count('teachers_directory'),
   studentAppUsers:VS_count('mobile_users','role','student'),onlineStudents:online.students,onlineTeachers:online.teachers,
   activeLicenseHash:p.getProperty('VS_LICENSE_KEY_HASH')||'',
   windowsVersion:p.getProperty('VS_WINDOWS_VERSION')||'',mobileVersion:CacheService.getScriptCache().get('VS_MOBILE_VERSION')||''};
  const lastActive=Math.max(Number(p.getProperty('VS_WINDOWS_LAST_ACTIVE')||0),Number(CacheService.getScriptCache().get('VS_ACTIVITY_AT')||0));
  const fields={lastSeenAt:{timestampValue:new Date(lastActive).toISOString()}};Object.keys(data).forEach(k=>fields[k]=VS_encode(data[k]));
  VS_central('post',':commit',{writes:[{update:{name:'projects/'+VS_CENTRAL_PROJECT+'/databases/(default)/documents/platform_school_summaries/'+VS_project(),fields:fields},
   updateTransforms:[{fieldPath:'reportedAt',setToServerValue:'REQUEST_TIME'}]}]},VS_monitorToken());
  p.setProperty('VS_MONITOR_LAST_SENT',String(Date.now()));
 }finally{lock.releaseLock();}
}
function VS_queueComplaint(b,role,source,personId){
 const message=String(b.message||'').trim();if(message.length<3||message.length>3000)throw new Error('Use 3–3000 characters for the problem');
 const id=VS_project()+'_'+VS_secret().slice(0,32);
 // The school's private queue keeps a report during internet/quota outages.
 const limitId=VS_hash((personId||'admin')+'/'+VS_day()),limit=VS_get('support_limits',limitId)||{count:0};
 if(limit.count>=5)throw new Error('Five reports per person per day are allowed');
 VS_set('support_limits',limitId,{count:limit.count+1});
 VS_set('support_outbox',id,{schoolId:VS_project(),source:source,role:role,message:message,version:String(b.version||'').slice(0,32),status:'open',createdAt:Date.now()});
 try{VS_flushSupport();}catch(err){console.warn(String(err.message||err));}
 return {queued:true};
}
function VS_flushSupport(){
 const token=VS_monitorToken();if(!token)return;
 const props=PropertiesService.getScriptProperties();if(Date.now()-Number(props.getProperty('VS_SUPPORT_LAST_SENT')||0)<31000)return;
 const raw=VS_firestore('post',':runQuery',{structuredQuery:{from:[{collectionId:'support_outbox'}],limit:1}})||[];
 if(!raw[0]||!raw[0].document)return;const report=VS_doc(raw[0].document),id=report.id;delete report.id;delete report.createdAt;
 const fields={};Object.keys(report).forEach(k=>fields[k]=VS_encode(report[k]));
 try{
  VS_central('post',':commit',{writes:[
   {update:{name:'projects/'+VS_CENTRAL_PROJECT+'/databases/(default)/documents/platform_complaints/'+id,fields:fields},currentDocument:{exists:false},updateTransforms:[{fieldPath:'createdAt',setToServerValue:'REQUEST_TIME'}]},
   {update:{name:'projects/'+VS_CENTRAL_PROJECT+'/databases/(default)/documents/platform_support_limits/'+VS_project(),fields:{complaintId:VS_encode(id)}},updateTransforms:[{fieldPath:'lastSentAt',setToServerValue:'REQUEST_TIME'}]}
  ]},token);
 }catch(err){if(err.httpCode!==409)throw err;}
 props.setProperty('VS_SUPPORT_LAST_SENT',String(Date.now()));VS_firestore('delete','support_outbox/'+encodeURIComponent(id));
}
function VS_setupMessaging(androidAppId,senderId){
 if(!/^\d+$/.test(String(senderId))||!new RegExp('^1:'+senderId+':android:[a-fA-F0-9]+$').test(String(androidAppId)))throw new Error('Use the Android app ID and project number from this school Firebase Android app (com.example.saarthi_ai)');
 PropertiesService.getScriptProperties().setProperties({VS_ANDROID_APP_ID:String(androidAppId),VS_FCM_SENDER_ID:String(senderId)});
 return {projectId:VS_project(),configured:true};
}
function VS_messagingOptions(){
 const p=PropertiesService.getScriptProperties(),appId=p.getProperty('VS_ANDROID_APP_ID'),sender=p.getProperty('VS_FCM_SENDER_ID');
 return appId&&sender?{projectId:VS_project(),apiKey:p.getProperty('VS_FIREBASE_API_KEY'),appId:appId,messagingSenderId:sender}:null;
}
function VS_notifySchoolNotice(id){
 if(!id||id.length>180)throw new Error('Invalid school notice');
 const notice=VS_get('school_notices',id);if(!notice)throw new Error('School notice has not synced yet');
 const job=VS_get('notification_jobs',VS_hash(id));if(job&&job.sent)return;
 if(!VS_messagingOptions())throw new Error('Complete this school Android messaging setup first');
 // Topics carry only an invalidation signal. Private titles/messages are fetched
 // through the recipient's authenticated school session, including in background.
 const r=UrlFetchApp.fetch('https://fcm.googleapis.com/v1/projects/'+encodeURIComponent(VS_project())+'/messages:send',{
  method:'post',contentType:'application/json',headers:{Authorization:'Bearer '+ScriptApp.getOAuthToken()},muteHttpExceptions:true,
  payload:JSON.stringify({message:{topic:'school_notices',data:{schoolId:VS_project(),type:'school_notice',noticeId:id},android:{priority:'high',ttl:'86400s'}}})});
 if(r.getResponseCode()!==200)throw new Error('School notification could not be sent. Check the school Cloud Messaging API and Apps Script permission.');
 VS_set('notification_jobs',VS_hash(id),{sent:true,sentAt:Date.now()});
}
function VS_platformMaintenance(){
 try{VS_publishMonitor();}catch(e){console.warn(String(e.message||e));}
 try{VS_flushSupport();}catch(e){console.warn(String(e.message||e));}
}

