// Backward compatible:
// - Website / Android ke existing action names unchanged hain.
// - Normal GET ab bhi success JSON deta hai.
// - Windows LED ke liye GET ?action=health_check ya POST
//   {"action":"health_check"} actual Apps Script + Google Drive
//   permission test karta hai.
// ============================================================

const SAARTHI_BACKEND_VERSION =
  "3.4-school-isolated";

function doGet(e) {
  const action = String(
    e &&
    e.parameter &&
    e.parameter.action
      ? e.parameter.action
      : ""
  ).trim();

  if (
    action === "health_check" ||
    action === "ping"
  ) {
    return healthCheck();
  }

  return jsonResponse({
    success: true,
    message: "Saarthi AI School API is running",
    version: SAARTHI_BACKEND_VERSION,
    healthCheck: "?action=health_check",
    actions: [
      "health_check",
      "ping",
      "windows_sync_snapshot",
      "windows_sync_text_snapshot",
      "sync_identity_get",
      "sync_identity_claim",
      "add_student",
      "edit_student",
      "delete_student",
      "change_student_class",
      "add_teacher",
      "edit_teacher",
      "delete_teacher",
      "update_teacher_schedule",
