// ============================================================
// HEALTH CHECK
// ============================================================

function healthCheck() {
  try {
    // Real Drive access test. Sirf URL alive hone se GREEN nahi hoga.
    // Drive permission/API kaam karega tabhi success true milega.
    const rootFolder =
      DriveApp.getRootFolder();

    const rootFolderId =
      rootFolder.getId();

    return jsonResponse({
      success: true,
      working: true,
      service: "google_drive_apps_script",
      message:
        "Google Apps Script + Google Drive backend working",
      version: SAARTHI_BACKEND_VERSION,
      rootFolderAccessible:
        !!rootFolderId,
      backendInstanceId:
        getOrCreateBackendInstanceId_(),
      timestamp:
        new Date().toISOString()
    });

  } catch (error) {

    console.error(
      "Backend health check failed:",
      error
    );

    return jsonResponse({
      success: false,
      working: false,
      service: "google_drive_apps_script",
      message:
        "Google backend health check failed",
      error: String(error),
      version: SAARTHI_BACKEND_VERSION,
      timestamp:
        new Date().toISOString()
    });
  }
}


// ============================================================
// SCHOOL / BACKEND IDENTITY
//
// Cross-school safety contract:
// - Every Apps Script deployment has a stable backendInstanceId.
// - Once a School Sync ID is claimed, another school's ID cannot overwrite it.
// - Windows compares this ID with Firebase school_config/windows_sync_identity
//   before any Firebase <-> Google merge is allowed.
// ============================================================

function syncIdentityGet() {
  try {
    const properties = PropertiesService.getScriptProperties();
    const schoolSyncId = String(
      properties.getProperty("SAARTHI_SCHOOL_SYNC_ID") || ""
    ).trim();

    return jsonResponse({
      success: true,
      schoolSyncId: schoolSyncId,
      backendInstanceId: getOrCreateBackendInstanceId_(),
      version: SAARTHI_BACKEND_VERSION,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    return jsonResponse({
      success: false,
      message: "Google backend identity read failed",
      error: String(error),
      version: SAARTHI_BACKEND_VERSION
    });
  }
}

function syncIdentityClaim(data) {
  const requested = String(
    data && data.schoolSyncId ? data.schoolSyncId : ""
  ).trim();

  if (!requested || requested.length < 8 || requested.length > 200) {
    return jsonResponse({
      success: false,
      code: "INVALID_SCHOOL_SYNC_ID",
      message: "Valid School Sync ID required"
    });
  }

  const lock = LockService.getScriptLock();
  lock.waitLock(30000);

  try {
    const properties = PropertiesService.getScriptProperties();
    const existing = String(
      properties.getProperty("SAARTHI_SCHOOL_SYNC_ID") || ""
    ).trim();

    if (existing && existing !== requested) {
      return jsonResponse({
        success: false,
        code: "SCHOOL_SYNC_ID_MISMATCH",
        message:
          "This Google backend is already linked to another school identity.",
        schoolSyncId: existing,
        backendInstanceId: getOrCreateBackendInstanceId_()
      });
    }

    if (!existing) {
      properties.setProperty(
        "SAARTHI_SCHOOL_SYNC_ID",
        requested
      );
    }

    return jsonResponse({
      success: true,
      schoolSyncId: requested,
      backendInstanceId: getOrCreateBackendInstanceId_(),
      claimed: !existing,
      version: SAARTHI_BACKEND_VERSION,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    return jsonResponse({
      success: false,
      message: "Google backend identity claim failed",
      error: String(error),
      version: SAARTHI_BACKEND_VERSION
    });
  } finally {
    lock.releaseLock();
  }
}

function getOrCreateBackendInstanceId_() {
  const properties = PropertiesService.getScriptProperties();
  let id = String(
    properties.getProperty("SAARTHI_BACKEND_INSTANCE_ID") || ""
  ).trim();

  if (!id) {
    id = "GB-" + Utilities.getUuid();
    properties.setProperty(
      "SAARTHI_BACKEND_INSTANCE_ID",
      id
    );
  }

  return id;
}


// ============================================================
// MAIN POST ROUTER
// ============================================================

function doPost(e) {
  // All legacy actions require verified school-admin proof. Mobile actions
  // are handled by the companion adapter, before the legacy router can run.
  const mobileResponse = VS_handleMobile(e);
  if (mobileResponse) return mobileResponse;
  try {

    if (
      !e ||
      !e.postData ||
      !e.postData.contents
    ) {
      throw new Error("Request body missing");
    }

    const data = JSON.parse(
      e.postData.contents
    );

    if (
      !data ||
      typeof data !== "object" ||
      Array.isArray(data)
    ) {
      throw new Error(
        "Invalid request data"
      );
    }

    const action =
      String(
        data.action || ""
      ).trim();

    // ========================================================
    // WINDOWS SCHOOL IDENTITY GUARD
    // ========================================================
    // Existing Website / Android requests do not send this field and remain
    // backward compatible. Windows isolated profiles DO send it. If a stale
    // app page points at another school's script, the request is rejected
    // before any read/write/delete action can run.
    if (
      action !== "sync_identity_get" &&
      action !== "sync_identity_claim" &&
      action !== "health_check" &&
      action !== "ping"
    ) {
      const expectedSchoolSyncId = String(
        data._windowsSchoolSyncId || ""
      ).trim();

      if (expectedSchoolSyncId) {
        const actualSchoolSyncId = String(
          PropertiesService.getScriptProperties()
            .getProperty("SAARTHI_SCHOOL_SYNC_ID") || ""
        ).trim();

        if (
          !actualSchoolSyncId ||
          actualSchoolSyncId !== expectedSchoolSyncId
        ) {
          return jsonResponse({
            success: false,
            code: "SCHOOL_SYNC_ID_MISMATCH",
            message:
              "Windows school isolation blocked this Google backend request."
          });
        }
      }
    }


    // ========================================================
    // HEALTH CHECK / WINDOWS LED
    // ========================================================

    if (
      action === "health_check" ||
      action === "ping"
    ) {
      return healthCheck();
    }

    if (action === "windows_sync_snapshot") {
      return windowsSyncSnapshot(data);
    }

    // Firebase-safe snapshot:
    // Media/files/Drive URLs are stripped before Firebase sync.
    // Full windows_sync_snapshot stays unchanged for Local/Google use.
    if (action === "windows_sync_text_snapshot") {
      return windowsSyncTextSnapshot(data);
    }

    if (action === "sync_identity_get") {
      return syncIdentityGet();
    }

    if (action === "sync_identity_claim") {
      return syncIdentityClaim(data);
    }


    // ========================================================
    // STUDENT ACTIONS
    // ========================================================

    if (action === "add_student") {
      return addStudent(data);
    }

    if (action === "edit_student") {
      return editStudent(data);
    }

    if (action === "delete_student") {
      return deleteStudent(data);
    }

    if (action === "change_student_class") {
      return changeStudentClass(data);
    }


    // ========================================================
    // TEACHER ACTIONS
    // ========================================================

    if (action === "add_teacher") {
      return addTeacher(data);
    }

    if (action === "edit_teacher") {
      return editTeacher(data);
    }

