// ============================================================
// GENERIC GOOGLE SHEET
// ============================================================

function getOrCreateDatabaseSheet(
  spreadsheetName,
  headers
) {

  let sheet = null;

  const schoolRoot = VS_schoolDriveRoot();
  const files = schoolRoot.getFilesByName(spreadsheetName);

  while (files.hasNext()) {

    const file =
      files.next();

    if (
      file.getMimeType() ===
      MimeType.GOOGLE_SHEETS
    ) {

      const spreadsheet =
        SpreadsheetApp.openById(
          file.getId()
        );

      sheet =
        spreadsheet
          .getSheets()[0];

      break;
    }
  }


  // Create if not found
  if (!sheet) {

    const spreadsheet =
      SpreadsheetApp.create(
        spreadsheetName
      );

    DriveApp.getFileById(spreadsheet.getId()).moveTo(schoolRoot);
    sheet =
      spreadsheet
        .getSheets()[0];
  }


  ensureHeaders(
    sheet,
    headers
  );

  return sheet;
}


// ============================================================
// HEADER CHECK
// ============================================================

function ensureHeaders(
  sheet,
  headers
) {

  if (
    sheet.getLastRow() === 0
  ) {

    sheet
      .getRange(
        1,
        1,
        1,
        headers.length
      )
      .setValues([
        headers
      ]);

    return;
  }


  const currentHeaders =
    sheet
      .getRange(
        1,
        1,
        1,
        Math.max(
          sheet.getLastColumn(),
          headers.length
        )
      )
      .getValues()[0];


  let needsUpdate = false;

  for (
    let i = 0;
    i < headers.length;
    i++
  ) {

    if (
      String(
        currentHeaders[i] || ""
      ).trim() !==
      headers[i]
    ) {

      needsUpdate = true;
      break;
    }
  }


  if (needsUpdate) {

    sheet
      .getRange(
        1,
        1,
        1,
        headers.length
      )
      .setValues([
        headers
      ]);
  }
}


// ============================================================
// ROLL NORMALIZATION
//
// 1
// 01
// 001
// 0001
//
// ALL = 1
// ============================================================

function normalizeRoll(value) {

  let roll =
    String(
      value === null ||
      value === undefined
        ? ""
        : value
    ).trim();


  if (!roll) {
    return "";
  }


  // Only numeric Roll Nos
  if (/^\d+$/.test(roll)) {

    roll =
      roll.replace(
        /^0+(?=\d)/,
        ""
      );

    return roll;
  }


  // Non-numeric fallback
  return roll.toLowerCase();
}


// ============================================================
// CLASS NORMALIZATION
// ============================================================

function normalizeClass(value) {

  return String(
    value || ""
  )
    .trim()
    .replace(/\s+/g, " ")
    .toLowerCase();
}


// ============================================================
// PHONE NORMALIZATION
// ============================================================

function normalizePhone(value) {

  let phone =
    String(
      value || ""
    ).replace(/\D/g, "");


  // +91 / 91 handling
  if (
    phone.length === 12 &&
    phone.startsWith("91")
  ) {

    phone =
      phone.substring(2);
  }


  return phone;
}


