// ============================================================
// ADD TEACHER
// ============================================================

function addTeacher(data) {

  const name =
    String(
      data.name || ""
    ).trim();

  const subject =
    String(
      data.subject ||
      data.department ||
      ""
    ).trim();

  const phone =
    normalizePhone(
      data.phone ||
      data.mobile ||
      data.contact
    );


  if (!name) {
    throw new Error(
      "Teacher Name required hai"
    );
  }

  if (!subject) {
    throw new Error(
      "Subject / Department required hai"
    );
  }

  if (
    !phone ||
    phone.length !== 10
  ) {

    throw new Error(
      "Valid 10 digit Mobile Number required hai"
    );
  }


  const sheet =
    getOrCreateDatabaseSheet(
      TEACHER_SHEET_NAME,
      TEACHER_HEADERS
    );


  // Same phone already registered?
  const existingRow =
    findTeacherRow(
      sheet,
      "",
      phone
    );


  if (existingRow !== -1) {

    throw new Error(
      "Is mobile number se teacher already registered hai"
    );
  }


  const teacherId =
    String(
      data.teacherId ||
      generateTeacherId()
    ).trim();


  let photoUrl = "";


  if (
    data.photoBase64 &&
    String(
      data.photoBase64
    ).trim()
  ) {

    const photo =
      uploadTeacherPhoto(
        Object.assign(
          {},
          data,
          {
            teacherId:
              teacherId
          }
        )
      );

    photoUrl =
      photo.url || "";

  } else if (
    data.photoUrl &&
    String(
      data.photoUrl
    ).trim()
  ) {

    photoUrl =
      String(
        data.photoUrl
      ).trim();
  }


  const schedule =
    data.schedule &&
    typeof data.schedule ===
      "object"
      ? data.schedule
      : {
          Monday: "",
          Tuesday: "",
          Wednesday: "",
          Thursday: "",
          Friday: "",
          Saturday: ""
        };


  sheet.appendRow([
    teacherId,

    name,

    data.designation ||
      "Teacher",

    subject,

    data.qualification ||
      "",

    phone,

    data.email ||
      "",

    data.dateOfBirth ||
      "",

    data.joiningDate ||
      "",

    data.address ||
      "",

    data.assignedClasses ||
      "",

    data.employmentType ||
      "Permanent",

    data.status ||
      "Active",

    photoUrl,

    JSON.stringify(
      schedule
    ),

    new Date()
  ]);


  return jsonResponse({
    success: true,
    action: "add_teacher",
    message:
      "Teacher added successfully",

    teacherId:
      teacherId,

    photoUrl:
      photoUrl
  });
}


