// ------------------------------------------------------------

function attendanceTimeZone() {
  return (
    Session.getScriptTimeZone() ||
    "Asia/Kolkata"
  );
}


function attendanceNowMeta() {
  const now = new Date();
  const timeZone = attendanceTimeZone();

  return {
    now: now,
    dateKey: Utilities.formatDate(
      now,
      timeZone,
      "yyyy-MM-dd"
    ),
    dateText: Utilities.formatDate(
      now,
      timeZone,
      "dd/MM/yyyy"
    ),
    timeText: Utilities.formatDate(
      now,
      timeZone,
      "hh:mm:ss a"
    )
  };
}


function normalizeAttendanceMode(value) {
  const mode = String(
    value || "entry"
  )
    .trim()
    .toLowerCase();

  if (
    mode === "exit" ||
    mode === "out" ||
    mode === "checkout" ||
    mode === "check-out"
  ) {
    return "exit";
  }

  return "entry";
}


function attendanceId(
  prefix,
  personId,
  dateKey
) {
  const cleanPerson =
    safeDriveFileName(
      personId || "UNKNOWN"
    );

  return (
    prefix +
    "-" +
    cleanPerson +
    "-" +
    String(dateKey || "")
      .replace(/\D/g, "")
  );
}


// ------------------------------------------------------------
// FIND ATTENDANCE ROW
// One person = one row per day.
// Duplicate scans never create duplicate attendance rows.
// ------------------------------------------------------------

function findAttendanceRow(
  sheet,
  idColumnIndex,
  personId,
  dateKey
) {
  const lastRow = sheet.getLastRow();

  if (lastRow <= 1) {
    return -1;
  }

  const values = sheet
    .getRange(
      2,
      1,
      lastRow - 1,
      sheet.getLastColumn()
    )
    .getValues();

  const targetId = String(
    personId || ""
  ).trim();

  const targetDate = String(
    dateKey || ""
  ).trim();

  for (
    let i = 0;
    i < values.length;
    i++
  ) {
    const rowPersonId = String(
      values[i][idColumnIndex - 1] || ""
    ).trim();

    // Date Key is column 6 in both attendance sheets.
    const rowDateKey = String(
      values[i][5] || ""
    ).trim();

    if (
      rowPersonId === targetId &&
      rowDateKey === targetDate
    ) {
      return i + 2;
    }
  }

  return -1;
}


