function markStudentAttendance(data) {
  const studentId = String(
    data.studentId ||
    data.personId ||
    data.id ||
    ""
  ).trim();

  let studentName = String(
    data.studentName ||
    data.name ||
    ""
  ).trim();

  let studentClass = String(
    data.studentClass ||
    data.class ||
    ""
  ).trim();

  let rollNo = String(
    data.rollNo ||
    data.roll ||
    ""
  ).trim();

  if (!studentId) {
    throw new Error(
      "Student ID required hai"
    );
  }

  // If class + roll are available, existing student sheet se
  // missing name/class/roll values fill karne ki koshish karega.
  if (studentClass && rollNo) {
    try {
      const studentSheet =
        getOrCreateDatabaseSheet(
          STUDENT_SHEET_NAME,
          STUDENT_HEADERS
        );

      const studentRow =
        findStudentRow(
          studentSheet,
          studentClass,
          rollNo
        );

      if (studentRow > 1) {
        const values =
          studentSheet
            .getRange(
              studentRow,
              1,
              1,
              STUDENT_HEADERS.length
            )
            .getValues()[0];

        if (!studentName) {
          studentName =
            String(values[0] || "").trim();
        }

        if (!studentClass) {
          studentClass =
            String(values[2] || "").trim();
        }

        if (!rollNo) {
          rollNo =
            String(values[3] || "").trim();
        }
      }
    } catch (lookupError) {
      console.log(
        "Student attendance lookup warning: " +
        lookupError
      );
    }
  }

  const meta = attendanceNowMeta();
  const mode =
    normalizeAttendanceMode(
      data.mode ||
      data.scanMode ||
      data.attendanceMode
    );

  const source = String(
    data.source ||
    data.scanSource ||
    "QR"
  ).trim();

  const markedBy = String(
    data.markedBy ||
    data.updatedBy ||
    ""
  ).trim();

  const sheet =
    getOrCreateDatabaseSheet(
      STUDENT_ATTENDANCE_SHEET_NAME,
      STUDENT_ATTENDANCE_HEADERS
    );

  const existingRow =
    findAttendanceRow(
      sheet,
      2,
      studentId,
      meta.dateKey
    );

  if (existingRow > 1) {
    const oldValues =
      sheet
        .getRange(
          existingRow,
          1,
          1,
          STUDENT_ATTENDANCE_HEADERS.length
        )
        .getValues()[0];

    const firstEntry =
      String(oldValues[7] || "").trim() ||
      meta.timeText;

    const oldExit =
      String(oldValues[9] || "").trim();

    const scanCount =
      Number(oldValues[11] || 0) + 1;

    const exitTime =
      mode === "exit"
        ? meta.timeText
        : oldExit;

    const status =
      mode === "exit"
        ? "EXIT"
        : "PRESENT";

    const rowValues = [
      String(oldValues[0] || attendanceId(
        "SAT",
        studentId,
        meta.dateKey
      )),
      studentId,
      studentName ||
        String(oldValues[2] || "") ||
        "Student",
      studentClass ||
        String(oldValues[3] || ""),
      rollNo ||
