function markTeacherAttendance(data) {
  let teacherId = String(
    data.teacherId ||
    data.personId ||
    data.id ||
    ""
  ).trim();

  let teacherName = String(
    data.teacherName ||
    data.name ||
    ""
  ).trim();

  let designation = String(
    data.designation ||
    ""
  ).trim();

  let phone =
    normalizePhone(
      data.phone ||
      data.mobile ||
      data.contact
    );

  if (!teacherId && !phone) {
    throw new Error(
      "Teacher ID ya Mobile Number required hai"
    );
  }

  // Existing teacher DB se details auto-fill karega.
  try {
    const teacherSheet =
      getOrCreateDatabaseSheet(
        TEACHER_SHEET_NAME,
        TEACHER_HEADERS
      );

    const teacherRow =
      findTeacherRow(
        teacherSheet,
        teacherId,
        phone
      );

    if (teacherRow > 1) {
      const values =
        teacherSheet
          .getRange(
            teacherRow,
            1,
            1,
            TEACHER_HEADERS.length
          )
          .getValues()[0];

      teacherId =
        teacherId ||
        String(values[0] || "").trim();

      teacherName =
        teacherName ||
        String(values[1] || "").trim();

      designation =
        designation ||
        String(values[2] || "").trim();

      phone =
        phone ||
        normalizePhone(values[5]);
    }
  } catch (lookupError) {
    console.log(
      "Teacher attendance lookup warning: " +
      lookupError
    );
  }

  if (!teacherId) {
    // Stable fallback for old records where only phone is available.
    teacherId = "PHONE-" + phone;
  }

  const meta = attendanceNowMeta();

  const mode =
    normalizeAttendanceMode(
      data.mode ||
      data.scanMode ||
      data.attendanceMode
    );

  const source = String(
    data.source ||
    data.scanSource ||
    "QR"
  ).trim();

  const markedBy = String(
    data.markedBy ||
    data.updatedBy ||
    ""
  ).trim();

