      designation ||
        String(oldValues[3] || ""),
      phone ||
        String(oldValues[4] || ""),
      meta.dateKey,
      meta.dateText,
      firstEntry,
      meta.timeText,
      exitTime,
      status,
      scanCount,
      source ||
