function saveExam(data) {
  const examName = String(data.examName || "").trim();
  const studentClass = String(
    data.studentClass ||
    data.class ||
    ""
  ).trim();

  const subjects = Array.isArray(data.subjects)
    ? data.subjects
        .map(function(value) {
          return String(value || "").trim();
        })
        .filter(function(value) {
          return !!value;
        })
    : [];

  const fullMarks = Number(data.fullMarks || 0);
  const passMarks = Number(data.passMarks || 0);

  if (!examName) {
    throw new Error("Exam name required hai");
  }

  if (!studentClass) {
    throw new Error("Class required hai");
  }

  if (!subjects.length) {
    throw new Error("Kam se kam ek subject required hai");
  }

  if (
    !isFinite(fullMarks) ||
    fullMarks <= 0
  ) {
    throw new Error("Full marks invalid hai");
  }

  if (
    !isFinite(passMarks) ||
    passMarks < 0 ||
    passMarks > fullMarks
  ) {
    throw new Error("Pass marks invalid hai");
  }

  const examId = String(
    data.examId ||
    (
      "EXM-" +
      new Date().getTime() +
      "-" +
      Utilities.getUuid()
        .substring(0, 6)
        .toUpperCase()
    )
  ).trim();

  const sheet = getOrCreateDatabaseSheet(
    EXAM_SHEET_NAME,
    EXAM_HEADERS
  );

  const rowValues = [
    examId,
    examName,
    studentClass,
    JSON.stringify(subjects),
    fullMarks,
    passMarks,
    String(data.createdBy || "").trim(),
    new Date()
  ];

  const existingRow = findRowByFirstColumn(
    sheet,
    examId
  );

  if (existingRow > 1) {
    sheet
      .getRange(
        existingRow,
        1,
        1,
        EXAM_HEADERS.length
      )
      .setValues([rowValues]);
  } else {
    sheet.appendRow(rowValues);
  }

  return jsonResponse({
    success: true,
    action: "save_exam",
    message: "Exam saved successfully",
    exam: {
      examId: examId,
      examName: examName,
      studentClass: studentClass,
      subjects: subjects,
      fullMarks: fullMarks,
      passMarks: passMarks,
      createdBy: String(data.createdBy || "").trim(),
      timestamp: new Date().getTime()
    },
    sheetUrl: sheet.getParent().getUrl()
  });
}


function saveExamResult(data) {
  const examId = String(data.examId || "").trim();
  const studentId = String(data.studentId || "").trim();

  if (!examId || !studentId) {
    throw new Error("Exam ID aur Student ID required hain");
  }

  const examSheet = getOrCreateDatabaseSheet(
    EXAM_SHEET_NAME,
    EXAM_HEADERS
  );

  const examRow = findRowByFirstColumn(
    examSheet,
    examId
  );

  if (examRow === -1) {
    throw new Error("Exam record nahi mila");
  }

  const examValues = examSheet
    .getRange(
      examRow,
      1,
      1,
      EXAM_HEADERS.length
    )
    .getValues()[0];

  let subjects = [];

  try {
    subjects = JSON.parse(
      String(examValues[3] || "[]")
    );
  } catch (_) {
    subjects = [];
  }

  if (!Array.isArray(subjects) || !subjects.length) {
    throw new Error("Exam subjects invalid hain");
  }

  const fullMarks = Number(examValues[4] || 0);
  const passMarks = Number(examValues[5] || 0);
  const incomingMarks =
    data.marks &&
    typeof data.marks === "object" &&
    !Array.isArray(data.marks)
      ? data.marks
      : {};

  const finalMarks = {};
  let total = 0;
  let passedEverySubject = true;

  subjects.forEach(function(subject) {
    const mark = Number(incomingMarks[subject]);

    if (
      !isFinite(mark) ||
      mark < 0 ||
      mark > fullMarks
    ) {
      throw new Error(
        subject +
        " marks 0 se " +
        fullMarks +
        " ke beech hona chahiye"
      );
    }

    finalMarks[subject] = mark;
    total += mark;

    if (mark < passMarks) {
      passedEverySubject = false;
    }
  });

  const maximum = fullMarks * subjects.length;
  const percentage = maximum > 0
    ? Number(
        (
          total * 100 / maximum
        ).toFixed(2)
      )
    : 0;

  const resultText =
    passedEverySubject
      ? "PASS"
      : "FAIL";

  const grade = examGrade(
    percentage,
    passedEverySubject
  );

  const exam = {
    examId: examId,
    examName: String(examValues[1] || ""),
    studentClass: String(examValues[2] || ""),
    subjects: subjects,
    fullMarks: fullMarks,
    passMarks: passMarks
  };

  const resultData = {
    examId: examId,
    examName: exam.examName,
    studentId: studentId,
    studentName: String(data.studentName || "").trim(),
    studentClass: String(
      data.studentClass ||
      data.class ||
      exam.studentClass
    ).trim(),
    rollNo: String(data.rollNo || data.roll || "").trim(),
    marks: finalMarks,
    total: total,
    maximum: maximum,
    percentage: percentage,
    grade: grade,
    result: resultText,
    updatedBy: String(data.updatedBy || "").trim()
  };

  const reportCard = createExamReportCardPdf(
    exam,
    resultData
  );

  const resultSheet = getOrCreateDatabaseSheet(
    EXAM_RESULT_SHEET_NAME,
    EXAM_RESULT_HEADERS
  );

  const rowValues = [
    examId,
    exam.examName,
    studentId,
    resultData.studentName,
    resultData.studentClass,
    resultData.rollNo,
    JSON.stringify(finalMarks),
    total,
    maximum,
    percentage,
    grade,
    resultText,
    reportCard.fileUrl,
    resultData.updatedBy,
    new Date()
  ];

  const existingRow = findExamResultRow(
    resultSheet,
    examId,
    studentId
  );

  if (existingRow > 1) {
    const oldUrl = String(
      resultSheet
        .getRange(
          existingRow,
          13
        )
        .getValue() ||
      ""
    ).trim();

    resultSheet
      .getRange(
        existingRow,
        1,
        1,
        EXAM_RESULT_HEADERS.length
      )
      .setValues([rowValues]);

    if (oldUrl && oldUrl !== reportCard.fileUrl) {
      try {
        const oldId = extractDriveFileId(oldUrl);
        if (oldId) {
          DriveApp
            .getFileById(oldId)
            .setTrashed(true);
        }
      } catch (error) {
        console.log(
          "Old report card delete warning: " +
          error
        );
      }
    }
  } else {
    resultSheet.appendRow(rowValues);
  }

  resultData.reportCardUrl =
    reportCard.fileUrl;
  resultData.timestamp =
    new Date().getTime();

  return jsonResponse({
    success: true,
    action: "save_exam_result",
    message:
      "Marks saved aur report card Google Drive me generate ho gaya",
    result: resultData,
    sheetUrl: resultSheet.getParent().getUrl()
  });
}


function createExamReportCardPdf(
  exam,
  result
) {
  const reportFolder = getOrCreateFolder(
    EXAM_REPORT_FOLDER
  );

  const tempName =
    "TEMP_REPORT_" +
    safeDriveFileName(exam.examName) +
    "_" +
    safeDriveFileName(result.studentName) +
    "_" +
    new Date().getTime();

  let tempSpreadsheet = null;
  let tempFile = null;

  try {
    // Report card PDF temporary Google Sheet se generate hota hai.
    // Existing backend already SpreadsheetApp + DriveApp permissions use karta hai.
    tempSpreadsheet = SpreadsheetApp.create(
      tempName
    );

    const sheet =
      tempSpreadsheet.getSheets()[0];

    sheet.setName("Report Card");

    try {
      sheet.setHiddenGridlines(true);
    } catch (_) {
      // Ignore if unavailable.
    }

    // --------------------------------------------------------
    // PAGE / COLUMN LAYOUT
    // --------------------------------------------------------
    sheet.setColumnWidth(1, 250);
    sheet.setColumnWidth(2, 105);
    sheet.setColumnWidth(3, 105);
    sheet.setColumnWidth(4, 105);

    // --------------------------------------------------------
    // SCHOOL HEADER
    // --------------------------------------------------------
    const schoolProfile = getSchoolProfileDataObject();

    sheet.getRange("A1:D1").merge();
    sheet
      .getRange("A1")
      .setValue(
        String(schoolProfile.schoolName || "School")
      )
      .setFontSize(17)
      .setFontWeight("bold")
      .setHorizontalAlignment("center")
      .setVerticalAlignment("middle")
      .setFontColor("#0B3558");

    sheet.setRowHeight(1, 34);

    sheet.getRange("A2:D2").merge();
    sheet
      .getRange("A2")
      .setValue("EXAM REPORT CARD")
      .setFontSize(14)
      .setFontWeight("bold")
      .setHorizontalAlignment("center")
      .setVerticalAlignment("middle")
      .setBackground("#E7F7F2")
      .setFontColor("#00796B");

    sheet.setRowHeight(2, 28);

    // --------------------------------------------------------
    // STUDENT / EXAM DETAILS
    // --------------------------------------------------------
    sheet.getRange("A4:D4").merge();
    sheet
      .getRange("A4")
      .setValue(
        "Exam: " +
        String(exam.examName || "")
      )
      .setFontWeight("bold")
      .setFontColor("#263238");

    sheet.getRange("A5:D5").merge();
    sheet
      .getRange("A5")
      .setValue(
        "Student: " +
        String(result.studentName || "")
      )
      .setFontWeight("bold")
      .setFontColor("#263238");

    sheet.getRange("A6:B6").merge();
    sheet
      .getRange("A6")
      .setValue(
        "Class: " +
        String(result.studentClass || "")
      )
      .setFontColor("#455A64");

    sheet.getRange("C6:D6").merge();
    sheet
      .getRange("C6")
      .setValue(
        "Roll: " +
        String(result.rollNo || "")
      )
      .setHorizontalAlignment("right")
      .setFontColor("#455A64");

    // --------------------------------------------------------
    // SUBJECT TABLE
    // --------------------------------------------------------
    const headerRow = 8;

    sheet
      .getRange(
        headerRow,
        1,
        1,
        4
      )
      .setValues([[
        "Subject",
        "Marks",
        "Full Marks",
        "Pass Marks"
      ]])
      .setFontWeight("bold")
      .setFontColor("#FFFFFF")
      .setBackground("#0B6E75")
      .setHorizontalAlignment("center")
      .setVerticalAlignment("middle")
      .setBorder(
        true,
        true,
        true,
        true,
        true,
        true
      );

    sheet.setRowHeight(headerRow, 28);

    const subjectRows = [];

    exam.subjects.forEach(function(subject) {
      subjectRows.push([
        String(subject),
        Number(result.marks[subject] || 0),
        Number(exam.fullMarks || 0),
        Number(exam.passMarks || 0)
      ]);
    });

    if (subjectRows.length > 0) {
      const subjectRange =
        sheet.getRange(
          headerRow + 1,
          1,
          subjectRows.length,
          4
        );

      subjectRange
        .setValues(subjectRows)
        .setVerticalAlignment("middle")
        .setBorder(
          true,
          true,
          true,
          true,
          true,
          true
        );

      sheet
        .getRange(
          headerRow + 1,
          2,
          subjectRows.length,
          3
        )
        .setHorizontalAlignment("center");

      for (
        let i = 0;
        i < subjectRows.length;
        i++
      ) {
        if (i % 2 === 1) {
          sheet
            .getRange(
              headerRow + 1 + i,
              1,
              1,
              4
            )
            .setBackground("#F7FAFB");
        }
      }
    }

    // --------------------------------------------------------
    // RESULT SUMMARY
    // --------------------------------------------------------
    const summaryStart =
      headerRow +
      subjectRows.length +
      2;

    sheet
      .getRange(
        summaryStart,
        1,
        1,
        2
      )
      .merge()
      .setValue("Total")
      .setFontWeight("bold")
      .setBackground("#EEF3F5");

    sheet
      .getRange(
        summaryStart,
        3,
        1,
        2
      )
      .merge()
      .setValue(
        String(result.total) +
        " / " +
        String(result.maximum)
      )
      .setFontWeight("bold")
      .setHorizontalAlignment("right")
      .setBackground("#EEF3F5");

    sheet
      .getRange(
        summaryStart + 1,
        1,
        1,
        2
      )
      .merge()
      .setValue("Percentage")
      .setFontWeight("bold");

    sheet
      .getRange(
        summaryStart + 1,
        3,
        1,
        2
      )
      .merge()
      .setValue(
        String(result.percentage) + "%"
      )
      .setFontWeight("bold")
      .setHorizontalAlignment("right");

    sheet
      .getRange(
        summaryStart + 2,
        1,
        1,
        2
      )
      .merge()
      .setValue("Grade")
      .setFontWeight("bold");

    sheet
      .getRange(
        summaryStart + 2,
        3,
        1,
        2
      )
      .merge()
      .setValue(
        String(result.grade || "")
      )
      .setFontWeight("bold")
      .setHorizontalAlignment("right");

    const passed =
      String(result.result || "")
        .toUpperCase() ===
      "PASS";

    const resultColor =
      passed
        ? "#00897B"
        : "#D32F2F";

    const resultBackground =
      passed
        ? "#E7F7F2"
        : "#FDECEC";

    sheet
      .getRange(
        summaryStart + 3,
        1,
        1,
        2
      )
      .merge()
      .setValue("Result")
      .setFontWeight("bold")
      .setBackground(resultBackground)
      .setFontColor(resultColor);

    sheet
      .getRange(
        summaryStart + 3,
        3,
        1,
        2
      )
      .merge()
      .setValue(
        String(result.result || "")
      )
      .setFontSize(13)
      .setFontWeight("bold")
      .setHorizontalAlignment("right")
      .setBackground(resultBackground)
      .setFontColor(resultColor);

    sheet
      .getRange(
        summaryStart,
        1,
        4,
        4
      )
      .setBorder(
        true,
        true,
        true,
        true,
        true,
        true
      );

    // --------------------------------------------------------
    // FOOTER
    // --------------------------------------------------------
    sheet
      .getRange(
        summaryStart + 5,
        3,
        1,
        2
      )
      .merge()
      .setValue(
        String(schoolProfile.principalName || "Principal") +
        "\nPrincipal"
      )
      .setHorizontalAlignment("center")
      .setFontSize(9)
      .setFontWeight("bold")
      .setFontColor("#455A64");

    sheet
      .getRange(
        summaryStart + 6,
        1,
        1,
        4
      )
      .merge()
      .setValue(
        "Generated by Vidya Saarthi"
      )
      .setHorizontalAlignment("center")
      .setFontSize(9)
      .setFontColor("#78909C");

    // Optional school logo / seal / principal signature from Drive.
    try {
      if (schoolProfile.logoFileId) {
        const logoBlob = VS_schoolFile(schoolProfile.logoFileId).getBlob();
        const logoImage = sheet.insertImage(logoBlob, 1, 1);
        logoImage.setWidth(48).setHeight(48);
      }
    } catch (logoError) {
      console.log("Report card logo warning: " + logoError);
    }

    try {
      if (schoolProfile.sealFileId) {
        const sealBlob = VS_schoolFile(schoolProfile.sealFileId).getBlob();
        const sealImage = sheet.insertImage(sealBlob, 1, summaryStart + 5);
        sealImage.setWidth(54).setHeight(54);
      }
    } catch (sealError) {
      console.log("Report card seal warning: " + sealError);
    }

    try {
      if (schoolProfile.principalSignatureFileId) {
        const signatureBlob = DriveApp
          .getFileById(schoolProfile.principalSignatureFileId)
          .getBlob();
        const signatureImage = sheet.insertImage(
          signatureBlob,
          3,
          summaryStart + 5
        );
        signatureImage.setWidth(90).setHeight(35);
      }
    } catch (signatureError) {
      console.log("Report card signature warning: " + signatureError);
    }

    const dataRange =
      sheet.getRange(
        1,
        1,
        summaryStart + 6,
        4
      );

    dataRange
      .setFontFamily("Arial")
      .setWrap(true)
      .setVerticalAlignment("middle");

    SpreadsheetApp.flush();

    Utilities.sleep(300);

    const pdfFileName =
      safeDriveFileName(exam.examName) +
      "_" +
      safeDriveFileName(result.studentClass) +
      "_Roll_" +
      safeDriveFileName(result.rollNo) +
      "_" +
      safeDriveFileName(result.studentName) +
      ".pdf";

    tempFile =
      DriveApp.getFileById(
        tempSpreadsheet.getId()
      );

    const pdfBlob =
      tempFile
        .getBlob()
        .getAs(MimeType.PDF)
        .setName(pdfFileName);

    const pdfFile =
      reportFolder.createFile(
        pdfBlob
      );

    return {
      fileId: pdfFile.getId(),
      fileUrl:
        "https://drive.google.com/file/d/" +
        pdfFile.getId() +
        "/view"
    };

  } finally {
    // Temporary Sheet clean-up.
    try {
      if (
        tempSpreadsheet &&
        !tempFile
      ) {
        tempFile =
          DriveApp.getFileById(
            tempSpreadsheet.getId()
          );
      }

      if (tempFile) {
        tempFile.setTrashed(true);
      }
    } catch (cleanupError) {
      console.log(
        "Temporary report sheet cleanup warning: " +
        cleanupError
      );
    }
  }
}


function examGrade(
  percentage,
  passed
) {
  if (!passed) return "F";
  if (percentage >= 90) return "A+";
  if (percentage >= 80) return "A";
  if (percentage >= 70) return "B+";
  if (percentage >= 60) return "B";
  if (percentage >= 50) return "C";
  if (percentage >= 40) return "D";
  return "E";
}


function findExamResultRow(
  sheet,
  examId,
  studentId
) {
  if (sheet.getLastRow() <= 1) {
    return -1;
  }

  const rows = sheet
    .getRange(
      2,
      1,
      sheet.getLastRow() - 1,
      3
    )
    .getValues();

  for (let i = 0; i < rows.length; i++) {
    if (
      String(rows[i][0] || "").trim() === examId &&
      String(rows[i][2] || "").trim() === studentId
    ) {
      return i + 2;
    }
  }

  return -1;
}


function findRowByFirstColumn(
  sheet,
  value
) {
  const target = String(value || "").trim();

  if (
    !target ||
    sheet.getLastRow() <= 1
  ) {
    return -1;
  }

  const values = sheet
    .getRange(
      2,
      1,
      sheet.getLastRow() - 1,
      1
    )
    .getValues();

  for (let i = 0; i < values.length; i++) {
    if (
      String(values[i][0] || "").trim() === target
    ) {
      return i + 2;
    }
  }

  return -1;
}


function getOrCreateChildFolder(
  parentFolder,
  folderName
) {
  const folders = parentFolder.getFoldersByName(
    folderName
  );

  if (folders.hasNext()) {
    return folders.next();
  }

  return parentFolder.createFolder(
    folderName
  );
}


function extractDriveFileId(url) {
  const value = String(url || "");

  let match = value.match(
    /\/d\/([^\/?]+)/i
  );

  if (!match) {
    match = value.match(
      /[?&]id=([^&]+)/i
    );
  }

  return match
    ? match[1]
    : "";
}


function dateToMillis(value) {
  if (
    Object.prototype.toString.call(value) ===
    "[object Date]"
  ) {
    return value.getTime();
  }

  const parsed = new Date(value);

  return isNaN(parsed.getTime())
    ? 0
    : parsed.getTime();
}


// ============================================================
// SAFE DRIVE FILE NAME
// ============================================================

function safeDriveFileName(value) {

  const cleaned =
    String(
      value || ""
    )
      .trim()
      .replace(
        /[\\/:*?"<>|#%{}[\]]/g,
        "_"
      )
      .replace(
        /\s+/g,
        "_"
      );

  return cleaned || "NA";
}


// ============================================================
// GENERIC IMAGE UPLOAD
// ============================================================

function uploadImageToDrive(
  folderName,
  data,
  defaultFileName
) {

  if (
    !data.photoBase64 ||
    !String(
      data.photoBase64
    ).trim()
  ) {

    throw new Error(
      "Photo Base64 missing"
    );
  }


  const folder =
    getOrCreateFolder(
      folderName
    );


  const base64Data =
    String(
      data.photoBase64
    ).replace(
      /^data:image\/[\w.+-]+;base64,/,
      ""
    );


  const bytes =
    Utilities.base64Decode(
      base64Data
    );


  const mimeType =
    String(
      data.photoMimeType ||
      "image/jpeg"
    );


  let extension = ".jpg";


  if (
    mimeType
      .toLowerCase()
      .includes("png")
  ) {

    extension = ".png";

  } else if (
    mimeType
      .toLowerCase()
      .includes("webp")
  ) {

    extension = ".webp";
  }


  const safeName =
    String(
      defaultFileName ||
      "Photo"
    )
      .replace(
        /[\\/:*?"<>|#%{}[\]]/g,
        "_"
      )
      .replace(
        /\s+/g,
        "_"
      );


  let fileName =
    safeName +
    extension;


  if (
    data.photoName &&
    String(
      data.photoName
    ).trim()
  ) {

    fileName =
      String(
        data.photoName
      ).trim();
  }


  const blob =
    Utilities.newBlob(
      bytes,
      mimeType,
      fileName
    );


  const photoFile =
    folder.createFile(
      blob
    );


  try {

    photoFile.setSharing(
      DriveApp.Access
        .ANYONE_WITH_LINK,

      DriveApp.Permission
        .VIEW
    );

  } catch (error) {

    console.log(
      "Photo sharing warning: " +
      error
    );
  }


  const fileId =
    photoFile.getId();


  const photoUrl =
    "https://lh3.googleusercontent.com/d/" +
    fileId +
    "=w800";


  return {
    success: true,
    fileId: fileId,
    url: photoUrl
  };
}


// ============================================================
// GET / CREATE FOLDER
// ============================================================

function getOrCreateFolder(
  folderName
) {

  const schoolRoot = VS_schoolDriveRoot();
  const folders = schoolRoot.getFoldersByName(folderName);


  if (folders.hasNext()) {

    return folders.next();
  }


  return schoolRoot.createFolder(folderName);
}


// ============================================================
// DELETE DRIVE PHOTO BY URL
// ============================================================

function deleteDrivePhotoByUrl(
  photoUrl
) {

  if (!photoUrl) {
    return false;
  }


  let match =
    String(
      photoUrl
    ).match(
      /googleusercontent\.com\/d\/([^=\/]+)/i
    );


  if (!match) {

    match =
      String(
        photoUrl
      ).match(
        /[?&]id=([^&]+)/i
      );
  }


  if (!match) {

    console.log(
      "Drive file ID nahi mila: " +
      photoUrl
    );

    return false;
  }


  const fileId =
    match[1];


  try {

    const file =
      VS_schoolFile(fileId);


    file.setTrashed(
      true
    );


    return true;

  } catch (error) {

    console.log(
      "Drive photo delete error: " +
      error
    );

    return false;
  }
}


// ============================================================
// JSON RESPONSE
// ============================================================

function jsonResponse(data) {
  const configuredProject = PropertiesService.getScriptProperties()
    .getProperty('VS_FIREBASE_PROJECT_ID');
  if (configuredProject) data = Object.assign({projectId: configuredProject}, data);

  return ContentService
    .createTextOutput(
      JSON.stringify(
        data
      )
    )
    .setMimeType(
      ContentService
        .MimeType
        .JSON
    );
}

/** School-owned Google storage. Never search the account's entire Drive by name. */
function VS_schoolDriveRoot(allowUnprepared) {
  const props = PropertiesService.getScriptProperties();
  const id = props.getProperty('VS_DRIVE_ROOT_ID');
  if (!id) throw new Error('Run VS_setupSchool before using school Google storage');
  const root = DriveApp.getFolderById(id);
  if (root.getDescription() !== 'SAARTHI_SCHOOL_PROJECT:' + VS_project()) {
    throw new Error('Google storage belongs to a different school');
  }
  if (!allowUnprepared && props.getProperty('VS_STORAGE_READY') !== 'true') {
    throw new Error('School owner must migrate existing files with VS_prepareSchoolStorage, or explicitly confirm an empty new school');
  }
  return root;
}

// Run from the Script editor as the school owner, never through the web router.
// Supply EXACT IDs of this school's legacy spreadsheets and top-level folders.
// Existing data is moved, never deleted or selected by an account-wide name.
function VS_prepareSchoolStorage(options) {
  options = options || {};
  const root = VS_schoolDriveRoot(true);
  const files = options.fileIds || [], folders = options.folderIds || [];
  if (!Array.isArray(files) || !Array.isArray(folders)) throw new Error('Supply arrays of exact Drive IDs');
  if (!files.length && !folders.length && options.startEmpty !== true) {
    throw new Error('Supply existing school file/folder IDs, or set startEmpty:true only for a new empty school');
  }
  const items = files.map(id => DriveApp.getFileById(String(id)))
    .concat(folders.map(id => DriveApp.getFolderById(String(id))));
  // Validate the entire selection before moving any file.
  items.forEach(item => VS_assertNoForeignSchoolParent(item));
  items.forEach(item => item.moveTo(root));
  PropertiesService.getScriptProperties().setProperty('VS_STORAGE_READY', 'true');
  return {projectId: VS_project(), rootFolderId: root.getId(), moved: items.length};
}

function VS_assertNoForeignSchoolParent(item) {
  const expected = 'SAARTHI_SCHOOL_PROJECT:' + VS_project();
  const seen = {};
  function visit(folder) {
    if (seen[folder.getId()]) return;
    seen[folder.getId()] = true;
    const tag = String(folder.getDescription() || '');
    if (tag.indexOf('SAARTHI_SCHOOL_PROJECT:') === 0 && tag !== expected) {
      throw new Error('Drive item belongs to another school; migration refused');
    }
    const parents = folder.getParents();
    while (parents.hasNext()) visit(parents.next());
  }
  if (typeof item.getDescription === 'function') {
    const tag = String(item.getDescription() || '');
    if (tag.indexOf('SAARTHI_SCHOOL_PROJECT:') === 0 && tag !== expected) {
      throw new Error('Drive folder belongs to another school; migration refused');
    }
  }
  const parents = item.getParents();
  while (parents.hasNext()) visit(parents.next());
}

function VS_schoolFile(fileId) {
  const file = DriveApp.getFileById(String(fileId));
  const rootId = VS_schoolDriveRoot().getId(), seen = {};
  function within(folder) {
    if (folder.getId() === rootId) return true;
    if (seen[folder.getId()]) return false;
    seen[folder.getId()] = true;
    const parents = folder.getParents();
    while (parents.hasNext()) if (within(parents.next())) return true;
    return false;
  }
  const parents = file.getParents();
  while (parents.hasNext()) if (within(parents.next())) return file;
  throw new Error('This Drive file does not belong to the configured school');
}

function VS_schoolSyncGuard(b) {
  if (['sync_identity_get', 'sync_identity_claim', 'health_check', 'ping'].indexOf(b.action) >= 0) return;
  const supplied = String(b._windowsSchoolSyncId || '').trim();
  const actual = String(PropertiesService.getScriptProperties().getProperty('SAARTHI_SCHOOL_SYNC_ID') || '').trim();
  if (supplied && supplied !== actual) throw new Error('Windows School Sync ID mismatch');
  // Also protects snapshots from silently returning an empty unmigrated school.
  VS_schoolDriveRoot();
}

function VS_mobileSchoolProfile() {
  const p = getSchoolProfileDataObject();
  const out = {};
  ['schoolName', 'principalName', 'schoolContactNo', 'latitude', 'longitude',
    'attendanceRadiusMeters'].forEach(k => { if (p[k] !== undefined) out[k] = p[k]; });
  return out;
}

function VS_personPhotoUrl(person, role) {
  if (role === 'student') {
    const sheet = getOrCreateDatabaseSheet(STUDENT_SHEET_NAME, STUDENT_HEADERS);
    const row = findStudentRow(sheet, person.class, person.rollNo);
    if (row < 2) return '';
    const values = sheet.getRange(row, 1, 1, STUDENT_HEADERS.length).getValues()[0];
    if (String(values[0] || '').trim().toLowerCase() !== String(person.name || '').trim().toLowerCase() ||
        VS_dob(values[STUDENT_HEADERS.indexOf('Date of Birth')]) !== VS_dob(person.dob || person.dateOfBirth)) return '';
    return String(values[STUDENT_HEADERS.indexOf('Photo URL')] || '');
  }
  const sheet = getOrCreateDatabaseSheet(TEACHER_SHEET_NAME, TEACHER_HEADERS);
  const row = findTeacherRow(sheet, person.teacherId || person.id, '');
  if (row < 2) return '';
  const values = sheet.getRange(row, 1, 1, TEACHER_HEADERS.length).getValues()[0];
  if (String(values[1] || '').trim().toLowerCase() !== String(person.name || '').trim().toLowerCase()) return '';
  return String(values[TEACHER_HEADERS.indexOf('Photo URL')] || '');
}

// The caller selects a kind, never a file ID, URL or another person's ID.
// Bytes come from this school's Google Drive, not Firestore.
function VS_mobileAsset(b, session) {
  let fileId = '';
  if (b.kind === 'photo') {
    const url = VS_personPhotoUrl(session.person, session.role);
    const match = url.match(/(?:googleusercontent\.com\/d\/|[?&]id=|\/file\/d\/)([A-Za-z0-9_-]+)/);
    fileId = match ? match[1] : '';
  } else if (b.kind === 'logo') {
    fileId = String(getSchoolProfileDataObject().logoFileId || '');
  } else throw new Error('Unsupported school asset');
  if (!fileId) return {available: false};
  const blob = VS_schoolFile(fileId).getBlob();
  if (!/^image\//.test(blob.getContentType()) || blob.getBytes().length > 2 * 1024 * 1024) {
    throw new Error('School image must be at most 2 MB');
  }
  return {available: true, mimeType: blob.getContentType(), base64: Utilities.base64Encode(blob.getBytes())};
}

rules:
rules_version = '2';

service cloud.firestore {
  match /databases/{database}/documents {

    // ============================================================
    // COMMON FUNCTIONS
    // ============================================================

    function signedIn() {
      return request.auth != null;
    }

    // Only an explicitly trusted administrator of THIS Firebase project.
    // Sign in again after the owner sets the custom claim.
    function isAdmin() {
      return signedIn() && (
        request.auth.token.get('admin', false) == true ||
        request.auth.token.get('role', '') == 'admin'
      );
    }

    // Firebase me media/file fields save nahi honge.
    // Photos/PDF/Documents/ID Card/Report Card/Receipt media
    // Google Drive + Local Storage me rahenge.
    function forbiddenMediaKeys() {
      return [
        'idCardUrl',
        'photoUrl',
        'photoBase64',
        'photoMimeType',

        'logoUrl',
        'logoFileId',
        'logoBase64',
        'logoMimeType',
        'logoFileName',

        'sealUrl',
        'sealFileId',
        'sealBase64',
        'sealMimeType',
        'sealFileName',

        'principalSignatureUrl',
        'principalSignatureFileId',
        'principalSignatureBase64',
        'principalSignatureMimeType',
        'principalSignatureFileName',

        'schoolLogoUrl',
        'schoolSealUrl',

        'reportCardUrl',
        'reportCardFileId',

        'receiptPdfUrl',
        'pdfBase64',

        'fileUrl',
        'fileId',
        'fileBase64',
        'downloadUrl',

        'driveUrl',
        'sheetUrl'
      ];
    }

    // CREATE me media/file key bilkul allowed nahi.
    function createHasNoMedia() {
      return !request.resource.data
        .keys()
        .hasAny(forbiddenMediaKeys());
    }

    // UPDATE me naya media/file field add/change nahi ho sakta.
    // Purana legacy media field unchanged reh sakta hai,
    // aur cleanup ke time delete kiya ja sakta hai.
    function updateDoesNotAddOrChangeMedia() {
      let diff = request.resource.data.diff(resource.data);

      return !diff
          .addedKeys()
          .hasAny(forbiddenMediaKeys())
        &&
        !diff
          .changedKeys()
          .hasAny(forbiddenMediaKeys());
    }


    // ============================================================
    // 1. USER PRIVATE DATA / AI CHAT HISTORY
    // ============================================================

    // ============================================================
    // 2. SCHOOL NOTICES — TEXT ONLY
    // ============================================================

    match /school_notices/{noticeId} {

      allow read: if isAdmin();

      allow create:
        if isAdmin()
        && request.resource.data.keys().hasOnly([
          'title',
          'description',
          'category',
          'timestamp',
          'lastEdited'
        ])
        && request.resource.data.title is string
        && request.resource.data.description is string
        && request.resource.data.category is string
        && request.resource.data.timestamp is int
        && request.resource.data.lastEdited is int;

      allow update:
        if isAdmin()
        && request.resource.data.keys().hasOnly([
          'title',
          'description',
          'category',
          'timestamp',
          'lastEdited'
        ])
        && request.resource.data.title is string
        && request.resource.data.description is string
        && request.resource.data.category is string
        && request.resource.data.timestamp is int
        && request.resource.data.lastEdited is int;

      allow delete:
        if isAdmin();
    }


    // ============================================================
    // 3. STUDENTS DIRECTORY — TEXT/NUMBER ONLY
    // ============================================================

    match /students_directory/{studentId} {

      allow read: if isAdmin();

      allow create:
        if isAdmin()
        && createHasNoMedia();

      allow update:
