    // ============================================================

    match /teachers_directory/{teacherId} {

      allow read:
        if isAdmin();

      allow create:
        if isAdmin()
        && createHasNoMedia();

      allow update:
        if isAdmin()
        && updateDoesNotAddOrChangeMedia();

      allow delete:
        if isAdmin();
    }


    // ============================================================
    // 5. SCHOOL CONFIG
    // Firebase connection/settings text allowed.
    // Branding media/URLs are blocked.
    // ============================================================

    match /school_config/{docId} {

      allow read:
        if isAdmin();

      allow create:
        if isAdmin()
        && createHasNoMedia();

      allow update:
        if isAdmin()
        && updateDoesNotAddOrChangeMedia();

      allow delete:
        if isAdmin();
