        && createHasNoMedia();

      allow update, delete:
        if false;
    }


    // ============================================================
    // FEES COLLECTION — TEXT/NUMBER ONLY IN FIREBASE
    // Receipt PDF + Drive/Sheet URL Firebase me nahi.
    // ============================================================

    match /fee_settings/{docId} {

      allow read:
        if isAdmin();

      allow create:
        if isAdmin()
        && createHasNoMedia();

      allow update:
